import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

// Resolve .env relative to the repo root, not the current working directory.
const envPath = path.join(path.dirname(fileURLToPath(import.meta.url)), '..', '.env');

function parseEnv(text) {
  const out = {};
  for (let line of text.replace(/^﻿/, '').split(/\r?\n/)) {
    line = line.trim();
    if (!line || line.startsWith('#')) continue;
    line = line.replace(/^export\s+/, '');
    const i = line.indexOf('=');
    if (i < 0) continue;
    const key = line.slice(0, i).trim();
    let val = line.slice(i + 1).trim();
    if (/^(['"]).*\1$/.test(val)) val = val.slice(1, -1);
    out[key] = val;
  }
  return out;
}

const fileEnv = fs.existsSync(envPath) ? parseEnv(fs.readFileSync(envPath, 'utf8')) : {};
const key = process.env.GEMINI_API_KEY || fileEnv.GEMINI_API_KEY;
if (!key) { console.error('Error: GEMINI_API_KEY is missing'); process.exit(1); }

